        public void save_state()
        {
            global::Cpp.Algo.copy(runoff.begin(), runoff.end(), old_runoff.begin());
            global::Cpp.Algo.copy(runon_inflow.begin(), runon_inflow.end(), old_runon_inflow.begin());
            global::Cpp.Algo.copy(conc.begin(), conc.end(), conc_old.begin());
            global::Cpp.Algo.copy(ponded_depth.begin(), ponded_depth.end(), old_ponded_depth.begin());
        }
        public void reset_state()
        {
