            global::Cpp.Algo.fill(old_gw_flow.begin(), old_gw_flow.end(), unchecked((double)(0.0)));
            global::Cpp.Algo.fill(snow_depth.begin(), snow_depth.end(), unchecked((double)(0.0)));
